using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

/// <summary>Tools available to the research agent.</summary>
public static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        // Uses the DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";

        try
        {
            var doc = await _http.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Abstract text
            if (doc.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                results.Add($"[Abstract] {abstractText}");

            // Related topics
            if (doc.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"[Result] {t}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings as you research.")]
    public static string SaveNote(string note)
    {
        _notes.Add(note);
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieve all saved research notes so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n---\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

// --- Main Program ---

Console.WriteLine("🔬 Research Agent");
Console.WriteLine(new string('─', 50));

// Configure the chat client with tools
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information (make multiple searches with different queries)
    2. Taking notes on key findings using the SaveNote tool
    3. After gathering enough information, retrieve your notes and produce a clear, well-organized summary

    Always search at least 2-3 different queries to get a well-rounded view of the topic.
    Save important findings as notes before producing your final summary.
    End with a structured summary that includes key points and sources.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

// Get research topic from user
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

messages.Add(new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"));

// Run the agent loop — stream the final response
await foreach (var update in agent.GetStreamingResponseAsync(messages, chatOptions))
{
    if (update.Text is { } text)
        Console.Write(text);
}

Console.WriteLine("\n\n✅ Research complete.");

