+/// <summary>Tools available to the research agent.</summary>
+public static class ResearchTools
+{
+    private static readonly List<string> _notes = [];
+    private static readonly HttpClient _http = new();
+
+    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
+    public static async Task<string> SearchWeb(string query)
+    {
+        // Uses the DuckDuckGo Instant Answer API (no key required)
+        var encoded = Uri.EscapeDataString(query);
+        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";
+
+        try
+        {
+            var doc = await _http.GetFromJsonAsync<JsonElement>(url);
+            var results = new List<string>();
+
+            // Abstract text
+            if (doc.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
+                results.Add($"[Abstract] {abstractText}");
+
+            // Related topics
+            if (doc.TryGetProperty("RelatedTopics", out var topics))
+            {
+                foreach (var topic in topics.EnumerateArray().Take(5))
+                {
+                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
+                        results.Add($"[Result] {t}");
+                }
+            }
+
+            return results.Count > 0
+                ? string.Join("\n\n", results)
+                : "No results found. Try rephrasing the query.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}";
+        }
+    }
+
+    [Description("Save a research note. Use this to record important findings as you research.")]
+    public static string SaveNote(string note)
+    {
+        _notes.Add(note);
+        return $"Note saved (total notes: {_notes.Count}).";
+    }
+
+    [Description("Retrieve all saved research notes so far.")]
+    public static string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+        return string.Join("\n---\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
+    }
+}

